package com.bank.portal.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import lombok.*;
@Entity @Table(name="transactions",indexes={@Index(name="idx_tx_card_date",columnList="card_id,transactionDate"),@Index(name="idx_tx_merchant",columnList="merchant_id")}) @Getter @Setter @NoArgsConstructor public class CardTransaction extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="card_id") private CreditCard card; @ManyToOne @JoinColumn(name="merchant_id") private Merchant merchant; @Column(nullable=false,precision=15,scale=2) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(nullable=false) private TransactionType transactionType; @Enumerated(EnumType.STRING) @Column(nullable=false) private TransactionStatus status; private String failureReason; @Column(nullable=false) private LocalDateTime transactionDate; @PrePersist void stamp(){if(transactionDate==null)transactionDate=LocalDateTime.now();} }
